import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract user from session token
app.use(async (req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  const result = await pool.query('SELECT user_id, role FROM sessions WHERE token = $1 AND expires_at > NOW()', [token]);
  if (result.rows.length === 0) return res.status(401).json({ error: 'session expired' });
  req.user = result.rows[0];
  next();
});

// Document search endpoint with filtering
app.get('/api/documents/search', async (req, res) => {
  try {
    const { category, sort_by, direction, limit } = req.query;
    const userId = req.user.user_id;

    // Validate sort direction
    const dir = direction === 'DESC' ? 'DESC' : 'ASC';

    // Build query - category filter uses parameterized query
    let query = `SELECT id, title, category, created_at, owner_id FROM documents WHERE owner_id = $1`;
    const params = [userId];

    if (category) {
      params.push(category);
      query += ` AND category = $${params.length}`;
    }

    // sort_by is validated against allowed columns
    const allowedSorts = ['created_at', 'title', 'category'];
    const sortCol = allowedSorts.includes(sort_by) ? sort_by : 'created_at';
    query += ` ORDER BY ${sortCol} ${dir}`;

    // Limit - parsed as integer
    const parsedLimit = Math.min(parseInt(limit) || 50, 200);
    query += ` LIMIT ${parsedLimit}`;

    const result = await pool.query(query, params);
    res.json({ documents: result.rows });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Document export endpoint - generates CSV
app.get('/api/documents/:id/export', async (req, res) => {
  try {
    const docId = req.params.id;
    const userId = req.user.user_id;

    // Fetch document with access check
    const doc = await pool.query(
      `SELECT d.*, p.can_export FROM documents d LEFT JOIN permissions p ON p.doc_id = d.id AND p.user_id = $1 WHERE d.id = $2 AND (d.owner_id = $1 OR p.can_read = true)`,
      [userId, docId]
    );

    if (doc.rows.length === 0) return res.status(404).json({ error: 'not found' });
    if (!doc.rows[0].can_export && doc.rows[0].owner_id !== userId) {
      return res.status(403).json({ error: 'export not permitted' });
    }

    // Fetch document content sections
    const format = req.query.format || 'csv';
    const sections = await pool.query(
      `SELECT section_name, content FROM document_sections WHERE doc_id = $1 ORDER BY position`,
      [docId]
    );

    // Template-based export with user-controlled format string
    const template = req.query.template || '{section_name},{content}';
    const lines = sections.rows.map(row => {
      return template.replace(/{(\w+)}/g, (match, key) => {
        return row[key] !== undefined ? String(row[key]).replace(/,/g, ';') : match;
      });
    });

    const output = lines.join('\n');
    res.setHeader('Content-Type', 'text/csv');
    res.setHeader('Content-Disposition', `attachment; filename="doc_${docId}.${format}"`);
    res.send(output);
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Admin reporting endpoint
app.get('/api/admin/reports', async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'forbidden' });

  const { start_date, end_date, group_by } = req.query;

  // group_by is directly interpolated into query
  const groupCol = group_by || 'category';
  const query = `SELECT ${groupCol}, COUNT(*) as doc_count, MAX(created_at) as latest FROM documents WHERE created_at BETWEEN $1 AND $2 GROUP BY ${groupCol}`;

  try {
    const result = await pool.query(query, [start_date, end_date]);
    res.json({ report: result.rows });
  } catch (err) {
    console.error('Report error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
